-- SwiftDictionary Update 2.4.0 — original Intermediate Quiz question bank (24 items).
-- Original learning content and Simplified Chinese translations; no third-party question text.
begin;
with seed(question_id,source_lesson_id,topic_id,difficulty,prompt_learning,prompt_zh,a_learning,a_zh,b_learning,b_zh,c_learning,c_zh,d_learning,d_zh,correct_option_id,explanation_learning,explanation_zh) as (
 values
('i-collocations-01','i-collocations','collocations','intermediate','Choose the natural collocation: “We need to ___ a decision before Friday.”','选择自然的词语搭配：“We need to ___ a decision before Friday.”','make,做出','do,做','take,拿','build,建立','a','The standard collocation is “make a decision.”','常见搭配是“make a decision”。'),
('i-collocations-02','i-collocations','collocations','intermediate','Which adjective naturally collocates with “rain”?','哪个形容词通常与“rain”搭配？','strong,强烈的','heavy,大','powerful,有力的','solid,坚固的','b','English commonly uses “heavy rain” to describe a large amount of rain.','英语通常用“heavy rain”表示大雨。'),
('i-collocations-03','i-collocations','collocations','intermediate','Complete the phrase: “take ___ for your actions.”','完成短语：“take ___ for your actions.”','attention,注意','responsibility,责任','decision,决定','progress,进展','b','The natural phrase is “take responsibility for” something.','自然表达是“take responsibility for”，表示对某事负责。'),
('i-collocations-04','i-collocations','collocations','intermediate','Choose the natural phrase.','选择自然的表达。','deeply asleep,深深地睡着','strongly asleep,强烈地睡着','heavily asleep,沉重地睡着','fully sleep,完全睡眠','a','“Deeply asleep” is a common collocation meaning in a very deep sleep.','“Deeply asleep”是常见搭配，表示睡得很沉。'),
('i-collocations-05','i-collocations','collocations','intermediate','Which phrase is most natural?','哪个短语最自然？','do a promise,做一个承诺','make a promise,作出承诺','take a promise,拿一个承诺','build a promise,建立承诺','b','The usual collocation is “make a promise.”','常见搭配是“make a promise”。'),
('i-conditionals-01','i-conditionals','conditional-sentences','intermediate','Choose the correct second conditional sentence.','选择正确的第二类条件句。','If I have more time, I would travel.,如果我有更多时间，我会旅行。','If I had more time, I would travel.,如果我有更多时间，我会去旅行。','If I had more time, I will travel.,如果我有更多时间，我将旅行。','If I would have more time, I travelled.,如果我会有更多时间，我旅行了。','b','The second conditional uses a past form in the if-clause and would + base verb in the result clause.','第二类条件句在if从句中使用过去式，在结果从句中使用would + 动词原形。'),
('i-conditionals-02','i-conditionals','conditional-sentences','intermediate','Complete the first conditional: “If it rains, we ___ indoors.”','完成第一类条件句：“If it rains, we ___ indoors.”','stay,stay','would stay,would stay','will stay,will stay','stayed,stayed','c','The first conditional uses present simple in the if-clause and will + base verb for a likely future result.','第一类条件句在if从句中使用一般现在时，结果从句常用will + 动词原形。'),
('i-conditionals-03','i-conditionals','conditional-sentences','intermediate','Which sentence describes an unreal past situation?','哪个句子描述与过去事实相反的情况？','If she studies, she will pass.,如果她学习，她会通过。','If she studied, she would pass.,如果她学习，她就会通过。','If she had studied, she would have passed.,如果她当时学习了，她就会通过。','If she studies, she passed.,如果她学习，她通过了。','c','The third conditional uses past perfect in the if-clause and would have + past participle in the result.','第三类条件句在if从句中使用过去完成时，结果从句使用would have + 过去分词。'),
('i-conditionals-04','i-conditionals','conditional-sentences','intermediate','Choose the closest meaning of “Unless you hurry, you will miss the train.”','选择“Unless you hurry, you will miss the train.”最接近的意思。','If you hurry, you will miss the train.,如果你赶快，你会错过火车。','If you do not hurry, you will miss the train.,如果你不赶快，你会错过火车。','Although you hurry, you will miss the train.,虽然你赶快了，你还是会错过火车。','When you hurry, you will miss the train.,当你赶快时，你会错过火车。','b','Unless means “if not,” so the sentence warns about the result of not hurrying.','unless表示“如果不”，所以这句话是在提醒不赶快的后果。'),
('i-conditionals-05','i-conditionals','conditional-sentences','intermediate','Choose the correct mixed conditional.','选择正确的混合条件句。','If I had gone to bed earlier, I would not be tired now.,如果我早点睡，现在就不会累了。','If I go to bed earlier, I would not be tired yesterday.,如果我早点睡，昨天就不会累。','If I went to bed earlier, I will not be tired now.,如果我早点睡，现在就不会累。','If I had gone to bed earlier, I will not be tired now.,如果我早点睡，现在就不会累。','a','A past condition can explain a present result: past perfect + would + base verb.','过去的条件可以解释现在的结果：过去完成时 + would + 动词原形。'),
('i-phrasal-01','i-phrasal','phrasal-verbs','intermediate','What does “look after” mean in “She looks after her younger brother”?','在“She looks after her younger brother”中，“look after”是什么意思？','search for,寻找','take care of,照顾','look at,看着','wait for,等待','b','“Look after” means to take care of someone or something.','“Look after”表示照顾某人或某物。'),
('i-phrasal-02','i-phrasal','phrasal-verbs','intermediate','Choose the meaning of “put off” in “They put off the meeting.”','在“They put off the meeting.”中，“put off”是什么意思？','cancel permanently,永久取消','postpone,推迟','organise,组织','attend,参加','b','“Put off” means to delay something until a later time.','“Put off”表示把某事推迟到以后。'),
('i-phrasal-03','i-phrasal','phrasal-verbs','intermediate','Which phrasal verb means to meet someone unexpectedly?','哪个短语动词表示意外遇见某人？','run into,偶然遇见','run out,用完','run over,碾过','run away,逃跑','a','“Run into someone” can mean to meet them by chance.','“Run into someone”可以表示偶然遇见某人。'),
('i-phrasal-04','i-phrasal','phrasal-verbs','intermediate','In “The committee carried out the plan,” what does “carried out” mean?','在“The committee carried out the plan.”中，“carried out”是什么意思？','criticised,批评','completed or performed,执行或实施','delayed,延迟','replaced,替换','b','“Carry out” means to perform, conduct or complete a task or plan.','“Carry out”表示执行、开展或完成任务或计划。'),
('i-phrasal-05','i-phrasal','phrasal-verbs','intermediate','What does “turn down an invitation” mean?','“turn down an invitation”是什么意思？','accept it,接受邀请','decline it,拒绝邀请','rewrite it,重写邀请','delay it,推迟邀请','b','“Turn down” means to refuse an offer or invitation.','“Turn down”表示拒绝提议或邀请。'),
('i-perfect-01','i-perfect','verb-tenses','intermediate','Choose the correct present perfect form: “They ___ the report already.”','选择正确的现在完成时形式：“They ___ the report already.”','finish,finish','have finished,have finished','had finish,had finish','are finish,are finish','b','The present perfect is formed with have/has + past participle.','现在完成时由have/has + 过去分词构成。'),
('i-perfect-02','i-perfect','verb-tenses','intermediate','Which sentence correctly describes an action that began in the past and continues now?','哪个句子正确描述了从过去开始并持续到现在的情况？','I live here since 2020.,我从2020年起住在这里。','I have lived here since 2020.,我从2020年起一直住在这里。','I lived here since 2020.,我从2020年起住在这里。','I am live here since 2020.,我从2020年起住在这里。','b','Use the present perfect with since to connect a starting point in the past to the present.','since与现在完成时连用，可把过去的起点连接到现在。'),
('i-perfect-03','i-perfect','verb-tenses','intermediate','Choose the correct past perfect sentence.','选择正确的过去完成时句子。','The train left before we arrived.,我们到达前火车已经开走了。','The train has left before we arrived.,我们到达前火车已经开走了。','The train had left before we arrived.,我们到达前火车已经开走了。','The train leaves before we arrived.,我们到达前火车已经开走了。','c','The past perfect marks the earlier of two past events: had left happened before arrived.','过去完成时表示两个过去动作中较早发生的动作：had left早于arrived。'),
('i-perfect-04','i-perfect','verb-tenses','intermediate','Choose the sentence that emphasises the duration of an ongoing activity.','选择强调持续进行时间的句子。','She has been studying for three hours.,她已经学习了三个小时。','She studies for three hours yesterday.,她昨天学习了三个小时。','She had study for three hours.,她已经学习了三个小时。','She is studied for three hours.,她已经学习了三个小时。','a','The present perfect continuous (has been studying) highlights an activity continuing over a period up to now.','现在完成进行时（has been studying）强调持续一段时间并延续到现在的活动。'),
('i-perfect-05','i-perfect','verb-tenses','intermediate','Choose the correct word: “I have known Daniel ___ five years.”','选择正确的词：“I have known Daniel ___ five years.”','since,自从','for,持续','during,在……期间','from,从','b','Use for with a length of time, such as five years; use since with a starting point.','for与时间长度连用，例如five years；since与起始时间点连用。'),
('i-word-01','i-word-families','word-formation','intermediate','Choose the noun form of “decide.”','选择“decide”的名词形式。','decisive,果断的','decision,决定','deciding,正在决定','decided,已决定的','b','Decision is the noun formed from the verb decide.','decision是动词decide对应的名词。'),
('i-word-02','i-word-families','word-formation','intermediate','Choose the adjective form of “success.”','选择“success”的形容词形式。','successfully,成功地','succeed,成功','successful,成功的','success,成功','c','Successful is the adjective; successfully is the adverb.','successful是形容词；successfully是副词。'),
('i-word-03','i-word-families','word-formation','intermediate','Complete the sentence: “The new design is very ___.”','完成句子：“The new design is very ___.”','create,创造','creation,创造物','creative,有创意的','creatively,有创意地','c','An adjective is needed after “is very”; creative describes the design.','“is very”后面需要形容词；creative用来描述设计。'),
('i-word-04','i-word-families','word-formation','intermediate','Choose the correct noun: “Her ___ surprised the whole team.”','选择正确的名词：“Her ___ surprised the whole team.”','arrive,到达','arrival,到达','arriving,正在到达','arrived,已到达','b','Arrival is the noun form of arrive and fits after the possessive her.','arrival是arrive的名词形式，适合放在物主限定词her后面。')
),
variants as (
 select question_id||'-zh' as question_id,source_lesson_id,topic_id,difficulty,'zh'::text as translation_language_code,
 prompt_learning,prompt_zh as prompt_translation,
 jsonb_build_array(jsonb_build_object('id','a','learning_text',a_learning,'translation_text',a_zh),jsonb_build_object('id','b','learning_text',b_learning,'translation_text',b_zh),jsonb_build_object('id','c','learning_text',c_learning,'translation_text',c_zh),jsonb_build_object('id','d','learning_text',d_learning,'translation_text',d_zh)) as options,
 correct_option_id,explanation_learning,explanation_zh as explanation_translation
 from seed
 union all
 select question_id||'-en',source_lesson_id,topic_id,difficulty,'en',prompt_learning,prompt_learning,
 jsonb_build_array(jsonb_build_object('id','a','learning_text',a_learning,'translation_text',a_learning),jsonb_build_object('id','b','learning_text',b_learning,'translation_text',b_learning),jsonb_build_object('id','c','learning_text',c_learning,'translation_text',c_learning),jsonb_build_object('id','d','learning_text',d_learning,'translation_text',d_learning)),
 correct_option_id,explanation_learning,explanation_learning from seed
)
insert into private.quiz_question_bank
(question_id,revision,learning_language_code,translation_language_code,source_lesson_id,topic_id,difficulty,prompt_learning,prompt_translation,options,correct_option_id,explanation_learning,explanation_translation,status,approved_at)
select question_id,1,'en',translation_language_code,source_lesson_id,topic_id,difficulty,prompt_learning,prompt_translation,options,correct_option_id,explanation_learning,explanation_translation,'approved',pg_catalog.now()
from variants on conflict (question_id,revision) do nothing;
commit;
